'use strict';
// Comms → SMS → Android gateway. Phones running Kade SMS Bridge send SMS from a Safaricom SIM.
// Everything here reads and writes /api/smsgw (lib/smsgw.cjs); nothing is simulated in the page.
(function(){
 const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const when=t=>t?new Date(t).toLocaleString('en-KE',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):'—';
 const ago=t=>{if(!t)return 'never';const s=Math.round((Date.now()-t)/1000);return s<60?s+' s ago':s<3600?Math.round(s/60)+' min ago':s<86400?Math.round(s/3600)+' h ago':Math.round(s/86400)+' d ago';};
 const n=v=>Number(v||0).toLocaleString('en-KE');
 const GSM='@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&\'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà',EXT='^{}\\[~]|€\f';
 const parts=t=>{let u=0,g=true;for(const c of t){if(GSM.includes(c))u++;else if(EXT.includes(c))u+=2;else{g=false;break;}}if(g)return {enc:'GSM-7',n:u<=160?(u?1:0):Math.ceil(u/153),len:u,per:u<=160?160:153};const l=[...t].length;return {enc:'Unicode',n:l<=70?(l?1:0):Math.ceil(l/67),len:l,per:l<=70?70:67};};
 const ST={queued:['Queued','warning'],scheduled:['Scheduled','warning'],sending:['On the phone','warning'],sent:['Sent','online'],delivered:['Delivered','online'],failed:['Failed','offline'],undelivered:['Not delivered','offline'],unknown:['Unknown','offline'],cancelled:['Cancelled','']};
 const pill=s=>{const [l,c]=ST[s]||[s,''];return `<span class="status ${c}">${E(l)}</span>`;};
 const view={tab:'overview',q:{status:'',channel:'',q:'',from:'',to:''},offset:0};
 let data=null,timer=null,curRoot=null;
 async function load(){data=await api('smsgw');return data;}
 window.kadeSmsGateway=async function(root){if(!root)return;curRoot=root;root.innerHTML='<section class="card"><p class="muted" style="padding:18px">Loading the Android gateway…</p></section>';
  try{await load();}catch(e){root.innerHTML=`<section class="card"><p class="muted" style="padding:18px">${E(e.message)}</p></section>`;return;}
  paint(root);clearInterval(timer);timer=setInterval(async()=>{if(!root.isConnected||root.hidden){clearInterval(timer);return;}if(!['overview','phones'].includes(view.tab))return;try{await load();paint(root,true);}catch{}},10000);};
 function paint(root,soft){const c=data.config,m=data.canManage;
  const mode=c.disabled?['Emergency off','offline']:c.mode==='on'?['On','online']:c.mode==='test'?['Test (test numbers only)','warning']:['Off',''];
  root.innerHTML=`${c.disabled?'<div class="gw-banner gw-bad"><b>Emergency off.</b> Phones send nothing; automatic messages use the commercial provider. Turn it back on in Settings.</div>':c.mode==='off'?'<div class="gw-banner">The Android gateway is <b>off</b>. Customer messages go through your commercial provider as before. Pair a phone, then switch to <b>Test</b> in Settings.</div>':''}
   ${data.bundles.low&&data.bundles.remaining!=null?`<div class="gw-banner gw-warn">SMS bundle running low: about <b>${n(data.bundles.remaining)}</b> SMS left (estimate). Buy a new bundle on the gateway SIM and record it under Bundles.</div>`:''}
   <div class="gw-head"><span>Gateway: <span class="status ${mode[1]}">${mode[0]}</span></span><div class="sms-tabs gw-tabs">${[['overview','Overview'],['phones','Phones'],['send','Send'],['history','Queue & history'],['bundles','Bundles'],['settings','Settings']].map(([k,l])=>`<button type="button" data-gw-tab="${k}" class="${view.tab===k?'on':''}">${l}</button>`).join('')}</div></div>
   <div id="gw-body"></div>`;
  for(const b of root.querySelectorAll('[data-gw-tab]'))b.onclick=()=>{view.tab=b.dataset.gwTab;paint(root);};
  const body=root.querySelector('#gw-body');({overview,phones,send,history,bundles,settings})[view.tab](body,root,soft);}
 // ---- Overview ----
 function overview(el){const d=data,s=d.stats,act=d.devices.filter(x=>x.status==='active'),on=act.filter(x=>x.online);
  el.innerHTML=`<div class="sms-stats">
   <div><small>PHONES ONLINE</small><b>${on.length}/${act.length}</b><span>${act.length?'last contact '+ago(Math.max(...act.map(x=>x.lastSeen||0))):'no phone paired yet'}</span></div>
   <div><small>SENT TODAY</small><b>${n(s.today.sent+s.today.delivered)}</b><span>${n(s.today.delivered)} delivery-confirmed</span></div>
   <div><small>THIS MONTH</small><b>${n(s.month.sent+s.month.delivered)}</b><span>${n(s.month.parts)} SMS units used</span></div>
   <div><small>PENDING</small><b>${n(s.pending)}</b><span>queued, scheduled or on a phone</span></div>
   <div><small>FAILED TODAY</small><b>${n(s.today.failed)}</b><span>${n(s.today.unknown)} with unknown result</span></div>
   <div><small>BUNDLE ESTIMATE</small><b>${d.bundles.remaining==null?'—':n(d.bundles.remaining)}</b><span>${d.bundles.remaining==null?'record a bundle to track it':'SMS left (estimate)'}</span></div></div>
   <section class="card"><div class="card-header"><div><h2>Phones</h2><p>Each phone reports every 20 seconds while the gateway app runs.</p></div>${data.canManage?'<button class="button primary" id="gw-add">Add phone</button>':''}</div><div class="gw-phones">${act.length?act.map(phoneCard).join(''):'<p class="muted" style="padding:0 18px 18px">No phone paired. Install Kade SMS Bridge on an Android phone with the Safaricom SIM, then press Add phone.</p>'}</div></section>
   <section class="card"><div class="card-header"><div><h2>Recent problems</h2><p>Failed, not delivered, or unknown (the phone took the message but never reported back; it is not retried automatically).</p></div></div>
   ${table(['TIME','TO','STATUS','DETAIL'],d.stats.errors,x=>`<tr><td>${when(x.time)}</td><td>${E(x.to)}</td><td>${pill(x.status)}</td><td>${E(x.error||'')}</td></tr>`,'No problems.')}</section>`;
  const a=el.querySelector('#gw-add');if(a)a.onclick=addPhone;wirePhones(el);}
 function phoneCard(x){const i=x.info||{},l=x.limits;return `<div class="gw-phone ${x.online?'':'gw-off'}"><div class="gw-phone-top"><b>${E(x.name)}</b>${x.isDefault?'<span class="status online">Default</span>':''}<span class="status ${x.online?'online':'offline'}">${x.online?'Online':'Offline'}</span>${x.paused?'<span class="status warning">Paused</span>':''}</div>
   <div class="gw-kv"><span>SIM</span><b>${E(i.operator||'—')} · ${E(i.simState||'—')}</b><span>Battery</span><b>${i.battery!=null?i.battery+'%':'—'}${i.charging?' · charging':''}</b><span>Network</span><b>${E(i.network||'—')}${i.signal?' · signal '+E(i.signal):''}</b><span>SMS permission</span><b>${i.smsPermission==='granted'?'Granted':'<span class="auth-bad">Missing</span>'}</b><span>Last contact</span><b>${ago(x.lastSeen)}</b><span>Phone</span><b>${E([i.manufacturer,i.model].filter(Boolean).join(' ')||'—')} · Android ${E(i.android||'?')} · app ${E(i.appVersion||'?')}</b><span>Limits</span><b>${l.perMinute}/min · ${n(l.daily)}/day · ${n(l.monthly)}/month (${n(x.allowance)} left now)</b></div>
   ${data.canManage?`<div class="gw-actions">${x.isDefault?'':`<button class="button secondary" data-gw-def="${x.id}">Make default</button>`}<button class="button secondary" data-gw-pause="${x.id}" data-p="${x.paused?0:1}">${x.paused?'Resume':'Pause'}</button><button class="button secondary" data-gw-lim="${x.id}">Limits</button><button class="button secondary" data-gw-rename="${x.id}">Rename</button><button class="button secondary" data-gw-repair="${x.id}">New pairing code</button><button class="button danger" data-gw-revoke="${x.id}">Revoke</button></div>`:''}</div>`;}
 function wirePhones(el){const dev=id=>data.devices.find(x=>x.id===id),re=async()=>{await load();paint(curRoot);};
  for(const b of el.querySelectorAll('[data-gw-def]'))b.onclick=async()=>{try{await api('smsgw/devices/'+b.dataset.gwDef,'PATCH',{isDefault:true});toast('Default phone changed');re();}catch(e){toast(e.message);}};
  for(const b of el.querySelectorAll('[data-gw-pause]'))b.onclick=async()=>{try{await api('smsgw/devices/'+b.dataset.gwPause,'PATCH',{paused:b.dataset.p==='1'});toast(b.dataset.p==='1'?'Phone paused':'Phone resumed');re();}catch(e){toast(e.message);}};
  for(const b of el.querySelectorAll('[data-gw-rename]'))b.onclick=async()=>{const v=prompt('New name for this phone',dev(b.dataset.gwRename).name);if(!v)return;try{await api('smsgw/devices/'+b.dataset.gwRename,'PATCH',{name:v});re();}catch(e){toast(e.message);}};
  for(const b of el.querySelectorAll('[data-gw-lim]'))b.onclick=()=>{const x=dev(b.dataset.gwLim),l=x.limits;showDetails('Sending limits · '+x.name,`<form id="gw-lim" class="radius-form"><p class="muted">Keep these within what your SIM and Safaricom bundle allow. Android itself also asks for confirmation after 30 SMS in 30 minutes unless that limit is raised on the phone (see the install guide).</p><div class="form-grid"><label>Per minute<input name="perMinute" type="number" min="1" max="30" value="${l.perMinute}"></label><label>Per day<input name="daily" type="number" min="1" max="5000" value="${l.daily}"></label><label>Per month<input name="monthly" type="number" min="1" max="100000" value="${l.monthly}"></label></div><button class="button primary">Save limits</button></form>`);
   $('#gw-lim').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('smsgw/devices/'+x.id,'PATCH',{limits:{perMinute:+f.perMinute,daily:+f.daily,monthly:+f.monthly}});$('#detail-dialog').close();toast('Limits saved');re();}catch(err){toast(err.message);}};};
  for(const b of el.querySelectorAll('[data-gw-repair]'))b.onclick=async()=>{try{showPair(await api('smsgw/devices/'+b.dataset.gwRepair+'/pair-code','POST',{}));}catch(e){toast(e.message);}};
  for(const b of el.querySelectorAll('[data-gw-revoke]'))b.onclick=async()=>{const x=dev(b.dataset.gwRevoke);if(!(await kdConfirm(`Revoke ${x.name}? It stops sending at once and its token stops working. Messages it has not taken go back to the queue.`)))return;try{await api('smsgw/devices/'+x.id+'/revoke','POST',{});toast('Phone revoked');re();}catch(e){toast(e.message);}};}
 async function addPhone(){const name=prompt('Name for this phone (e.g. "Office Safaricom phone")','');if(name===null)return;try{showPair(await api('smsgw/devices','POST',{name}));}catch(e){toast(e.message);}}
 function showPair(r){const link=`kadesms://pair?server=${encodeURIComponent(r.server)}&code=${r.code}`;let qr='';try{qr=window.kadeQRPng?window.kadeQRPng(link,6):'';}catch{}
  showDetails('Pair '+r.device.name,`<div class="gw-pair"><ol><li>On the Android phone with the Safaricom SIM, install <b>Kade SMS Bridge</b>: <a href="${E(data.apk)}" download>download the app</a> (allow "install unknown apps" when asked).</li><li>Open it and tap <b>Scan pairing QR code</b>, then scan this code. Or tap <b>Enter the code instead</b> and type <b>${r.code}</b>.</li><li>Allow SMS and notifications, and let it run in the background.</li></ol>
   ${qr?`<img src="${qr}" alt="Pairing QR code" class="gw-qr">`:''}<p class="gw-code">${r.code.slice(0,4)} ${r.code.slice(4)}</p><p class="muted small">Single use. Expires at ${new Date(r.expiresAt).toLocaleTimeString()}. Once paired, the phone can be anywhere with internet.</p></div>`);}
 function phones(el){overview(el);const s=el.querySelector('.sms-stats');if(s)s.remove();const r=el.querySelectorAll('section.card')[1];if(r)r.remove();
  const rev=data.devices.filter(x=>x.status!=='active');if(rev.length)el.insertAdjacentHTML('beforeend',`<section class="card"><div class="card-header"><div><h2>Not active</h2><p>Waiting for pairing, or revoked.</p></div></div>${table(['PHONE','STATE','SINCE'],rev,x=>`<tr><td>${E(x.name)}</td><td>${x.status==='revoked'?'Revoked':x.pairing?'Waiting for pairing':'Pairing code expired'}</td><td>${when(x.revokedAt||x.createdAt)}</td></tr>`)}</section>`);}
 // ---- Send ----
 function send(el){const c=data.config,act=data.devices.filter(x=>x.status==='active');
  el.innerHTML=`<section class="card"><form id="gw-send" class="radius-form"><h2>Send SMS</h2><p class="muted">Placeholders such as {name}, {username}, {plan}, {expiry} are filled in for each customer. ${c.mode==='test'?'<b>Test mode:</b> only the test numbers in Settings can receive messages through the gateway.':''}</p>
   <div class="form-grid"><label>Send to<select name="target" id="gw-target"><option value="numbers">Phone numbers I type</option><option value="all">All customers</option><option value="active">Active customers</option><option value="hotspot">Hotspot customers</option><option value="pppoe">PPPoE customers</option><option value="static">Static IP customers</option><option value="expiring3">Expiring in 3 days</option><option value="expired7">Expired in the last 7 days</option></select></label>
   <label id="gw-to-l">Phone numbers<input name="to" placeholder="0712 345 678, 0722 …"></label>
   <label>Template<select id="gw-tpl"><option value="">— Write a message —</option></select></label>
   <label>Send through<select name="channel"><option value="android">Android gateway${act.length?'':' (no phone paired)'}</option><option value="commercial">Commercial SMS provider</option></select></label>
   <label>Phone<select name="deviceId"><option value="">Default phone (any online)</option>${act.map(x=>`<option value="${x.id}">${E(x.name)}</option>`).join('')}</select></label>
   <label>Schedule (optional)<input name="sendAt" type="datetime-local"></label></div>
   <label>Message<textarea name="message" id="gw-msg" rows="4" maxlength="900" required></textarea></label><small class="tpl-count" id="gw-count"></small>
   <label class="check-label"><input type="checkbox" name="promotional" id="gw-promo"> This is a promotion (customers who replied STOP are skipped; "${E(c.optOutText.trim())}" is added)</label>
   <button class="button primary">Queue SMS</button><div id="gw-progress"></div></form></section>`;
  const msg=$('#gw-msg'),cnt=()=>{let t=msg.value;if($('#gw-promo').checked&&t&&!/\bSTOP\b/i.test(t))t+=c.optOutText;const p=parts(t);$('#gw-count').textContent=t?`${p.len} characters · ${p.enc} · ${p.n} SMS part${p.n===1?'':'s'} per person`:'';};msg.oninput=cnt;$('#gw-promo').onchange=cnt;
  const tg=$('#gw-target'),tl=$('#gw-to-l');tg.onchange=()=>{tl.hidden=tg.value!=='numbers';};
  api('sms-templates').then(r=>{const s=$('#gw-tpl');if(!s)return;s.insertAdjacentHTML('beforeend',r.items.filter(t=>t.active!==false).map(t=>`<option value="${E(t.id)}">${E(t.name)}</option>`).join(''));s.onchange=()=>{const t=r.items.find(x=>x.id===s.value);if(t){msg.value=t.content;cnt();}};}).catch(()=>{});
  $('#gw-send').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),btn=e.target.querySelector('button.primary');
   const input={message:f.message,channel:f.channel,deviceId:f.deviceId||null,promotional:!!f.promotional,sendAt:f.sendAt?new Date(f.sendAt).toISOString():null,idempotencyKey:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random())};
   if(f.target==='numbers'){if(!f.to.trim()){toast('Type at least one number');return;}input.to=f.to;}else input.segment=f.target;
   btn.disabled=true;try{let r;try{r=await api('smsgw/send','POST',input);}catch(err){const m=/Confirm the number of recipients \((\d+)\)/.exec(err.message);if(!m)throw err;
     if(!(await kdConfirm(`Send this ${input.promotional?'promotion':'message'} to ${m[1]} people${input.sendAt?' at '+new Date(input.sendAt).toLocaleString():''}? Each gets ${parts(f.message).n} SMS part(s).`)))return;r=await api('smsgw/send','POST',{...input,confirm:Number(m[1])});}
    const sk=Object.entries(r.skipped).filter(([,v])=>v).map(([k,v])=>v+' '+k).join(', ');toast(`Queued ${r.queued} SMS${sk?' · skipped '+sk:''}`);track(r.batch);}
   catch(err){toast(err.message);}finally{btn.disabled=false;}};}
 async function track(batch){const el=$('#gw-progress');if(!el)return;for(let i=0;i<90&&el.isConnected;i++){let p;try{p=await api('smsgw/progress/'+batch);}catch{return;}
   const tot=Object.values(p).reduce((a,b)=>a+b,0),done=(p.sent||0)+(p.delivered||0)+(p.failed||0)+(p.unknown||0)+(p.undelivered||0)+(p.cancelled||0);
   el.innerHTML=`<div class="gw-prog"><div style="width:${tot?Math.round(done/tot*100):0}%"></div></div><small>${Object.entries(p).map(([k,v])=>`${(ST[k]||[k])[0]}: ${v}`).join(' · ')}</small>`;if(done>=tot&&!p.scheduled)return;await new Promise(r=>setTimeout(r,4000));}}
 // ---- Queue & history ----
 async function history(el){const q=view.q;
  el.innerHTML=`<section class="card"><div class="filters-card gw-filters"><label>Status<select id="gwq-status"><option value="">All</option><option value="pending">Pending</option>${Object.entries(ST).map(([k,[l]])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>Channel<select id="gwq-channel"><option value="">All</option><option value="android">Android gateway</option><option value="commercial">Commercial</option></select></label><label>Search<input id="gwq-q" placeholder="Number or text"></label><label>From<input id="gwq-from" type="date"></label><label>To<input id="gwq-to" type="date"></label><a class="button secondary" id="gwq-csv">Export CSV</a></div><div id="gwq-list"><p class="muted" style="padding:18px">Loading…</p></div></section>`;
  for(const k of ['status','channel','q','from','to']){const i=$('#gwq-'+k);i.value=q[k];i.onchange=i.oninput=()=>{q[k]=i.value;view.offset=0;list();};}
  const qs=()=>new URLSearchParams({...(q.status?{status:q.status}:{}),...(q.channel?{channel:q.channel}:{}),...(q.q?{q:q.q}:{}),...(q.from?{from:new Date(q.from+'T00:00').getTime()}:{}),...(q.to?{to:new Date(q.to+'T23:59:59').getTime()}:{})});
  let t;const list=()=>{clearTimeout(t);t=setTimeout(async()=>{$('#gwq-csv').href='/api/smsgw/jobs.csv?'+qs();let r;try{r=await api('smsgw/jobs?'+qs()+'&limit=100&offset='+view.offset);}catch(e){$('#gwq-list').innerHTML=`<p class="muted" style="padding:18px">${E(e.message)}</p>`;return;}
   $('#gwq-list').innerHTML=table(['CREATED','TO','TYPE','CHANNEL','STATUS','PARTS','DETAIL','MESSAGE',''],r.items,j=>`<tr><td>${when(j.createdAt)}${j.status==='scheduled'?`<small>for ${when(j.sendAt)}</small>`:''}</td><td>${E(j.to)}</td><td>${E(j.kind)}</td><td>${j.channel==='android'?'Android'+(j.deviceName?'<small>'+E(j.deviceName)+'</small>':''):'Commercial'+(j.failover?'<small>fail-over</small>':'')}</td><td>${pill(j.status)}${j.test?'<small>test</small>':''}</td><td>${j.parts}</td><td>${E(j.error||j.note||'')}${j.sentAt?`<small>sent ${when(j.sentAt)}</small>`:''}${j.deliveredAt?`<small>delivered ${when(j.deliveredAt)}</small>`:''}</td><td class="gw-msgcell">${E(j.message)}</td><td>${['queued','scheduled'].includes(j.status)?`<button class="ra-btn" data-gwq-cancel="${j.id}"><span>Cancel</span></button>`:''}${['failed','unknown','undelivered','cancelled'].includes(j.status)?`<button class="ra-btn" data-gwq-resend="${j.id}" data-st="${j.status}"><span>Send again</span></button>`:''}</td></tr>`,'No messages match.')+`<p class="muted small" style="padding:8px 18px">${r.total} message(s)${r.total>view.offset+100?` · <button class="link-button" id="gwq-more">next 100</button>`:''}${view.offset?` · <button class="link-button" id="gwq-prev">previous</button>`:''}</p>`;
   const mo=$('#gwq-more');if(mo)mo.onclick=()=>{view.offset+=100;list();};const pv=$('#gwq-prev');if(pv)pv.onclick=()=>{view.offset=Math.max(0,view.offset-100);list();};
   for(const b of document.querySelectorAll('[data-gwq-cancel]'))b.onclick=async()=>{try{await api('smsgw/jobs/'+b.dataset.gwqCancel+'/cancel','POST',{});toast('Cancelled');list();}catch(e){toast(e.message);}};
   for(const b of document.querySelectorAll('[data-gwq-resend]'))b.onclick=async()=>{const unk=b.dataset.st==='unknown';if(!(await kdConfirm(unk?'The result of this message is unknown: it may already have reached the customer. Send it again anyway?':'Send this message again?')))return;try{await api('smsgw/jobs/'+b.dataset.gwqResend+'/resend','POST',{confirm:true});toast('Queued again');list();}catch(e){toast(e.message);}};},200);};
  list();}
 // ---- Bundles ----
 function bundles(el){const b=data.bundles,m=data.canManage,today=new Date().toISOString().slice(0,10);
  el.innerHTML=`<section class="card"><div class="card-header"><div><h2>SMS bundles</h2><p>Record each Safaricom SMS bundle bought for the gateway SIM. Kade Cloud estimates what is left from the SMS units its phones sent (a long message uses several units). It cannot read the SIM's real balance, so check it on the phone from time to time.</p></div></div>
   <div class="sms-stats" style="margin:0 18px 14px"><div><small>ESTIMATED LEFT</small><b>${b.remaining==null?'—':n(b.remaining)}</b><span>${b.active} active bundle(s)</span></div><div><small>LOW-BALANCE WARNING</small><b>${n(data.config.lowBalance)}</b><span>change in Settings</span></div></div>
   ${m?`<form id="gw-bundle" class="radius-form"><div class="form-grid"><label>Bundle name<input name="name" required placeholder="e.g. Safaricom 1000 SMS weekly"></label><label>SMS quantity<input name="quantity" type="number" min="1" required></label><label>Price paid (KSh)<input name="price" type="number" min="0" step="0.01" value="0"></label><label>Bought on<input name="purchasedAt" type="date" value="${today}" required></label><label>Expires on<input name="expiresAt" type="date"></label></div><button class="button primary">Record bundle</button></form>`:''}
   ${table(['BUNDLE','QUANTITY','PRICE','BOUGHT','EXPIRES','USED','LEFT',''],b.items,x=>`<tr><td>${E(x.name)}</td><td>${n(x.quantity)}</td><td>KSh ${n(x.price)}</td><td>${when(x.purchasedAt)}</td><td>${x.expiresAt?when(x.expiresAt):'—'}${x.expired?'<small>expired</small>':''}</td><td>${n(x.used)}</td><td><b>${n(x.remaining)}</b></td><td>${m?`<button class="ra-btn" data-gwb-del="${x.id}"><span>Remove</span></button>`:''}</td></tr>`,'No bundles recorded.')}</section>`;
  const f=$('#gw-bundle');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));try{await api('smsgw/bundles','POST',{...v,quantity:+v.quantity,price:+v.price,purchasedAt:v.purchasedAt+'T00:00:00+03:00',expiresAt:v.expiresAt?v.expiresAt+'T23:59:59+03:00':null});toast('Bundle recorded');await load();bundles(el);}catch(err){toast(err.message);}};
  for(const x of el.querySelectorAll('[data-gwb-del]'))x.onclick=async()=>{if(!(await kdConfirm('Remove this bundle record? Sent messages are not affected.')))return;try{await api('smsgw/bundles/'+x.dataset.gwbDel,'DELETE');await load();bundles(el);}catch(e){toast(e.message);}};}
 // ---- Settings ----
 function settings(el){const c=data.config,m=data.canManage,cats=data.categories;
  el.innerHTML=`<section class="card"><form id="gw-cfg" class="radius-form"><h2>Gateway settings</h2>${m?'':'<p class="muted">Only admins can change these.</p>'}
   <fieldset class="gw-mode"><legend>Mode</legend>${[['off','Off','Nothing goes through the phones. Your commercial provider sends everything, as before.'],['test','Test','Only the test numbers below receive messages through the phones. Use this to check a new phone.'],['on','On','The message types ticked below go through the phones when one is online.']].map(([k,l,d])=>`<label class="check-label"><input type="radio" name="mode" value="${k}" ${c.mode===k?'checked':''}> <b>${l}</b> — ${d}</label>`).join('')}</fieldset>
   <fieldset class="gw-route"><legend>Send through the phones (when On)</legend>${Object.entries(cats).map(([k,v])=>`<label class="check-label"><input type="checkbox" name="route_${k}" ${c.routes[k]?'checked':''}> ${E(v.label)} <small class="muted">(${v.kinds.join(', ')})</small></label>`).join('')}<p class="muted small">Always on the commercial provider: ${data.critical.join(', ')} (codes, sign-in and staff alerts need the most reliable route).</p></fieldset>
   <div class="form-grid"><label>Test numbers<textarea name="testNumbers" rows="2" placeholder="0712345678, 0722…">${E(c.testNumbers.map(p=>String(p).replace(/^\+?254/,'0')).join(', '))}</textarea></label>
   <label>Fail-over after (minutes)<input name="failoverMinutes" type="number" min="2" max="1440" value="${c.failoverMinutes}"></label>
   <label>Warn when bundle below<input name="lowBalance" type="number" min="0" value="${c.lowBalance}"></label></div>
   <label class="check-label"><input type="checkbox" name="failover" ${c.failover?'checked':''}> If no phone takes a message within the fail-over time, send it through the commercial provider (only messages no phone took, so nothing is sent twice)</label>
   ${m?'<button class="button primary">Save settings</button>':''}</form></section>
   <section class="card gw-kill"><div class="card-header"><div><h2>Emergency off</h2><p>Stops all phones at once. Automatic messages go through the commercial provider. Queued messages wait.</p></div>${m?`<button class="button ${c.disabled?'primary':'danger'}" id="gw-kill">${c.disabled?'Turn the gateway back on':'Emergency off'}</button>`:''}</div></section>
   <section class="card"><div class="card-header"><div><h2>Opted out of promotions</h2><p>Customers who replied STOP to the gateway phone (or that staff added). Promotions skip them on every provider; service messages still go.</p></div></div>
   <form id="gw-opt" class="radius-form"><div class="form-grid"><label>Phone number<input name="phone" placeholder="07…" required></label></div><button class="button secondary">Add to opt-out list</button></form>
   ${table(['PHONE','SINCE','SOURCE',''],data.optOuts,o=>`<tr><td>${E(o.phone)}</td><td>${when(o.time)}</td><td>${E(o.source||'')}</td><td><button class="ra-btn" data-gw-optin="${E(o.phone)}"><span>Remove</span></button></td></tr>`,'Nobody has opted out.')}</section>`;
  const f=$('#gw-cfg');f.onsubmit=async e=>{e.preventDefault();const v=new FormData(f);const input={mode:v.get('mode'),routes:Object.fromEntries(Object.keys(cats).map(k=>[k,v.get('route_'+k)==='on'])),testNumbers:String(v.get('testNumbers')||''),failover:v.get('failover')==='on',failoverMinutes:+v.get('failoverMinutes'),lowBalance:+v.get('lowBalance')};
   if(input.mode==='on'&&c.mode!=='on'&&!(await kdConfirm('Switch the Android gateway on? The ticked customer messages will go out from the phone SIM from now on.')))return;
   try{await api('smsgw/config','PUT',input);toast('Gateway settings saved');await load();paint(curRoot);}catch(err){toast(err.message);}};
  const k=$('#gw-kill');if(k)k.onclick=async()=>{const off=!c.disabled;if(off&&!(await kdConfirm('Emergency off: stop all phones now?')))return;try{await api('smsgw/config','PUT',{disabled:off});toast(off?'Gateway stopped':'Gateway back on');await load();paint(curRoot);}catch(e){toast(e.message);}};
  $('#gw-opt').onsubmit=async e=>{e.preventDefault();try{await api('smsgw/opt-out','POST',{phone:new FormData(e.target).get('phone'),optedOut:true});await load();settings(el);}catch(err){toast(err.message);}};
  for(const b of el.querySelectorAll('[data-gw-optin]'))b.onclick=async()=>{if(!(await kdConfirm('Remove '+b.dataset.gwOptin+' from the opt-out list? They will receive promotions again.')))return;try{await api('smsgw/opt-out','POST',{phone:b.dataset.gwOptin,optedOut:false});await load();settings(el);}catch(e){toast(e.message);}};}
})();
